/**
 * ---------------------------------------------------------------------------
 * IMAGE REGISTRY
 * ---------------------------------------------------------------------------
 * Every image used on the site is declared here once. Components never
 * hard-code a path.
 *
 * Each entry has:
 *   src     Path under /public
 *   width   Intrinsic width in px  (prevents layout shift)
 *   height  Intrinsic height in px
 *   blurDataURL  10px base64 preview — gives the blur-up effect
 *   prompt  An AI image-generation prompt describing what belongs here
 *   alt     Real alt text. While it is `null` the `prompt` is used as the alt
 *           attribute so you can see what to generate.
 *
 * >>> BEFORE LAUNCH: replace the file at `src`, then write a short, factual
 * >>> `alt` for every image. Prompts are NOT valid alt text for real users.
 * See docs/IMAGES.md for the full workflow.
 * ---------------------------------------------------------------------------
 */

const P = '/images/placeholders/';

/** @type {(img: {alt: string|null, prompt: string}) => string} */
export function imageAlt(img) {
  if (!img) return '';
  return img.alt ?? img.prompt;
}


